<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model;
class SalesQuotation extends Model { use HasUuids; protected $fillable=['tenant_id','company_id','branch_id','customer_id','customer_contact_id','opportunity_id','currency_id','assigned_salesperson_id','price_list_id','current_version_id','created_by','number','state','valid_until','quotation_date','customer_reference','approval_status','response_status','conversion_status','version_number','payment_terms','delivery_terms','terms_and_conditions','customer_notes','internal_notes','additional_charges','accepted_at','converted_order_id','subtotal','discount_total','tax_total','total']; protected function casts():array{return ['valid_until'=>'date','quotation_date'=>'date','accepted_at'=>'datetime','version_number'=>'integer','additional_charges'=>'decimal:6'];} public function items(){return $this->hasMany(SalesQuotationItem::class,'quotation_id');} public function customer(){return $this->belongsTo(Customer::class);} public function contact(){return $this->belongsTo(CustomerContact::class,'customer_contact_id');} public function opportunity(){return $this->belongsTo(Opportunity::class);} public function order(){return $this->hasOne(SalesOrder::class,'quotation_id');} public function versions(){return $this->hasMany(SalesQuotationVersion::class,'quotation_id');} public function approvals(){return $this->hasMany(SalesQuotationApproval::class,'quotation_id');} public function responses(){return $this->hasMany(SalesQuotationResponse::class,'quotation_id');} public function communications(){return $this->hasMany(SalesQuotationCommunication::class,'quotation_id');} }
